import { z } from 'zod';
import { runRecordSchema, templateAggregateSchema, templateRegistryEntrySchema } from '@/lib/validation/schemas';
import raw from './fixtures.generated.json';

const fixturesSchema = z.object({
  templates: z.array(templateRegistryEntrySchema),
  aggregates: z.array(templateAggregateSchema),
  runs: z.array(runRecordSchema),
});

export type MockFixtures = z.infer<typeof fixturesSchema>;

let cached: MockFixtures | null = null;

/** Synthetic demo data (generated by scripts/generate-mock-fixtures.ts). Validated once on first use. */
export function loadMockFixtures(): MockFixtures {
  if (!cached) cached = fixturesSchema.parse(raw);
  return cached;
}
